/*
 * floor_detector.h
 * ================
 * One-sided lower-bound check on sub-stage times. A skipped loop makes a
 * sub-stage shorter, so alarm if any sub-stage is below F x its clean median.
 * Integer compare only; the table is generated by scripts/calibrate_floor.py.
 * Design and results: see docs/MAHALANOBIS_ANALYSIS.md and STATUS.md.
 */

#ifndef FLOOR_DETECTOR_H
#define FLOOR_DETECTOR_H

#include <stdint.h>

#define FLOOR_NUM_CP 8

/* Minimum plausible cycles per [checkpoint][sub_a, sub_b, sub_c]. Zero disables a cell. */
extern const uint16_t FLOOR_TABLE[FLOOR_NUM_CP][3];

/* Returns 1 if any sub-stage of checkpoint cp is below its floor (or cp is out of range). */
uint8_t floor_check(uint32_t cp, const uint32_t sub[3]);

#endif /* FLOOR_DETECTOR_H */
